prompt --application/pages/page_00006
begin
wwv_flow_imp_page.create_page(
 p_id=>6
,p_name=>'Detalle Bar'
,p_alias=>'DETALLE-BAR'
,p_step_title=>'Detalle Bar'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const API_BASE = ''https://parranderos-api-xdo0.onrender.com/bares'';',
'const barId = parseInt(apex.item(''P6_BAR_ID'').getValue());',
'',
'function cargarComentarios() {',
'  fetch(API_BASE + ''/'' + barId + ''/comentarios'')',
'    .then(function(res) { return res.json(); })',
'    .then(function(data) {',
'      const container = document.getElementById(''comentarios-container'');',
'      if (data.length === 0) {',
unistr('        container.innerHTML = ''<p>No hay comentarios a\00FAn. \00A1S\00E9 el primero!</p>'';'),
'        return;',
'      }',
'      let html = '''';',
'      data.forEach(function(c) {',
'        html += ''<div style="border:1px solid #ddd; border-radius:8px; padding:12px; margin-bottom:10px;">'';',
unistr('        html += ''<strong>'' + (c.autor || ''An\00F3nimo'') + ''</strong>'';'),
'        html += ''<p style="margin-top:6px;">'' + c.texto + ''</p>'';',
'        html += ''</div>'';',
'      });',
'      container.innerHTML = html;',
'    });',
'}',
'',
'function enviarComentario() {',
'  const texto = document.getElementById(''texto-comentario'').value;',
'  if (!texto.trim()) return;',
'  fetch(API_BASE + ''/'' + barId + ''/comentarios'', {',
'    method: ''POST'',',
'    headers: { ''Content-Type'': ''application/json'' },',
'    body: JSON.stringify({ bar_id: barId, texto: texto, autor: apex.env.APP_USER })',
'  })',
'  .then(function(res) { return res.json(); })',
'  .then(function() {',
'    document.getElementById(''texto-comentario'').value = '''';',
'    cargarComentarios();',
'  });',
'}',
'',
'function cargarEventos() {',
'  fetch(API_BASE + ''/'' + barId + ''/eventos'')',
'    .then(function(res) { return res.json(); })',
'    .then(function(data) {',
'      const container = document.getElementById(''eventos-container'');',
'      if (data.length === 0) {',
unistr('        container.innerHTML = ''<p>No hay eventos a\00FAn.</p>'';'),
'        return;',
'      }',
'      let html = '''';',
'      data.forEach(function(e) {',
'        html += ''<div style="border:1px solid #ddd; border-radius:8px; padding:12px; margin-bottom:10px;">'';',
'        html += ''<strong>'' + e.nombre + ''</strong>'';',
'        Object.keys(e).forEach(function(key) {',
'          if (key !== ''nombre'' && key !== ''bar_id'' && key !== ''_id'' && key !== ''fecha_creacion'') {',
'            html += ''<p>'' + key + '': '' + e[key] + ''</p>'';',
'          }',
'        });',
'        html += ''</div>'';',
'      });',
'      container.innerHTML = html;',
'    });',
'}',
'',
'function enviarEvento() {',
'  const nombre = document.getElementById(''evento-nombre'').value;',
'  if (!nombre.trim()) return;',
'  const campo1 = document.getElementById(''evento-campo1'').value;',
'  const campo2 = document.getElementById(''evento-campo2'').value;',
'  const evento = { nombre: nombre };',
'  if (campo1.trim()) evento.campo1 = campo1;',
'  if (campo2.trim()) evento.campo2 = campo2;',
'  fetch(API_BASE + ''/'' + barId + ''/eventos'', {',
'    method: ''POST'',',
'    headers: { ''Content-Type'': ''application/json'' },',
'    body: JSON.stringify(evento)',
'  })',
'  .then(function(res) { return res.json(); })',
'  .then(function() {',
'    document.getElementById(''evento-nombre'').value = '''';',
'    document.getElementById(''evento-campo1'').value = '''';',
'    document.getElementById(''evento-campo2'').value = '''';',
'    cargarEventos();',
'  });',
'}',
'',
'window.enviarComentario = enviarComentario;',
'window.enviarEvento = enviarEvento;',
'cargarComentarios();',
'cargarEventos();'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'03'
,p_last_updated_by=>'CO_B331_SQL_S53_ADMIN'
,p_last_upd_yyyymmddhh24miss=>'20260517041509'
);
